<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ───────────────────────────────────────────────────────────
   image plane quad → 4 × CylinderGeometry rods (r .035)      #1A1A1A
   camera centre O  → SphereGeometry(0.22)                    #1A1A1A
   3D point P       → SphereGeometry(0.22)                    #1A1A1A
   image point p    → SphereGeometry(0.12)                    #1A1A1A
   solid ray O→P    → CylinderGeometry rod (r .035)           #00E000
   dashed ray O→P+Ṗ → pool of rods, 0.18/0.12 dash            #00E000
   arrow Ṗ at P     → cylinder shaft (r .05) + cone head      #FF0000
   arrow ṗ at p     → cylinder shaft (r .033) + cone head     #FF0000
   ghost P / ghost p/ trail (animation) → spheres + Line      #1A1A1A / #00E000
   labels O, P, p, Ṗ, ṗ → addLabel, bold serif                black
   World = camera frame: O = origin, +Z → screen-right toward P,
   +Y → screen-up, +X → recedes up-left.  f = 2.5.
─────────────────────────────────────────────────────────────────────────────*/

const F = 2.5;
const GREEN = 0x00E000, RED = 0xFF0000, DARK = 0x1A1A1A;
const UPV = new THREE.Vector3(0, 1, 0);

const CYL = new THREE.CylinderGeometry(1, 1, 1, 14);
const CONE = new THREE.ConeGeometry(1, 1, 20);
const SPH = new THREE.SphereGeometry(1, 24, 18);

function makeRod(color, opacity) {
  const m = new THREE.Mesh(CYL, new THREE.MeshBasicMaterial({
    color, transparent: opacity !== undefined, opacity: opacity === undefined ? 1 : opacity
  }));
  scene.add(m);
  return m;
}
function setRod(mesh, a, b, radius) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UPV, dir.clone().normalize());
  mesh.scale.set(radius, len, radius);
}
function makeDot(radius, color, opacity) {
  const m = new THREE.Mesh(SPH, new THREE.MeshBasicMaterial({
    color, transparent: opacity !== undefined, opacity: opacity === undefined ? 1 : opacity
  }));
  m.scale.setScalar(radius);
  scene.add(m);
  return m;
}
function makeArrow(color, shaftR) {
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(CYL, mat);
  const head = new THREE.Mesh(CONE, mat);
  const g = new THREE.Group();
  g.add(shaft); g.add(head);
  scene.add(g);
  return {
    group: g, shaft, head,
    set(origin, vec) {
      const len = vec.length();
      if (len < 1e-3) { g.visible = false; return; }
      g.visible = true;
      const dir = vec.clone().divideScalar(len);
      const q = new THREE.Quaternion().setFromUnitVectors(UPV, dir);
      const headLen = Math.min(len * 0.45, shaftR * 6.5);
      const headR = shaftR * 2.5;
      const shaftLen = Math.max(len - headLen, 1e-4);
      shaft.position.copy(origin).addScaledVector(dir, shaftLen / 2);
      shaft.quaternion.copy(q);
      shaft.scale.set(shaftR, shaftLen, shaftR);
      head.position.copy(origin).addScaledVector(dir, shaftLen + headLen / 2);
      head.quaternion.copy(q);
      head.scale.set(headR, headLen, headR);
    }
  };
}

/* ── image plane quad (Z = F, X ∈ [-1.7,1.7], Y ∈ [-2.6,2.6]) ─────────────── */
const HW = 1.7, HH = 2.6;
const quadCorners = [
  new THREE.Vector3(-HW, -HH, F), new THREE.Vector3(-HW, HH, F),
  new THREE.Vector3(HW, HH, F), new THREE.Vector3(HW, -HH, F)
];
const quadRods = [];
for (let i = 0; i < 4; i++) {
  const r = makeRod(DARK);
  setRod(r, quadCorners[i], quadCorners[(i + 1) % 4], 0.038);
  quadRods.push(r);
}
registerInteractive(quadRods[0], {
  title: 'Image plane',
  tooltip: 'Image plane at Z = f',
  body: 'The image plane sits at Z = f = 2.5 in front of the camera centre O. Every 3D point is imaged where the ray from O to that point pierces this plane: x = fX/Z, y = fY/Z.'
});

/* ── points, rays, arrows ─────────────────────────────────────────────────── */
const dotO = makeDot(0.22, DARK);
const dotP = makeDot(0.22, DARK);
const dotp = makeDot(0.12, DARK);
const rayRod = makeRod(GREEN);
const arrowP = makeArrow(RED, 0.05);
const arrowp = makeArrow(RED, 0.033);

const dashPool = [];
for (let i = 0; i < 150; i++) { const r = makeRod(GREEN); r.visible = false; dashPool.push(r); }
function setDashed(a, b, dash, gap, radius) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) { dashPool.forEach(r => r.visible = false); return; }
  dir.divideScalar(len);
  let t = 0, i = 0;
  const pa = new THREE.Vector3(), pb = new THREE.Vector3();
  while (t < len && i < dashPool.length) {
    const t2 = Math.min(t + dash, len);
    pa.copy(a).addScaledVector(dir, t);
    pb.copy(a).addScaledVector(dir, t2);
    setRod(dashPool[i], pa, pb, radius);
    i++; t = t2 + gap;
  }
  for (; i < dashPool.length; i++) dashPool[i].visible = false;
}

/* ── animation ghosts + trail ─────────────────────────────────────────────── */
const ghostP = makeDot(0.18, 0x444444, 0.55); ghostP.visible = false;
const ghostp = makeDot(0.10, 0x444444, 0.65); ghostp.visible = false;
const ghostRay = makeRod(GREEN, 0.45); ghostRay.visible = false;
const TRAIL_MAX = 400;
const trailPos = new Float32Array(TRAIL_MAX * 3);
const trailGeom = new THREE.BufferGeometry();
trailGeom.setAttribute('position', new THREE.BufferAttribute(trailPos, 3));
trailGeom.setDrawRange(0, 0);
const trailLine = new THREE.Line(trailGeom, new THREE.LineBasicMaterial({
  color: GREEN, transparent: true, opacity: 0.75
}));
trailLine.frustumCulled = false;
scene.add(trailLine);
let trailCount = 0;

/* ── state ────────────────────────────────────────────────────────────────── */
const state = {
  P: new THREE.Vector3(0.35, 1.0, 9.0),
  xdot: 0.2, ydot: 0.8, zdot: -2.0
};
const tween = { active: false, from: null, to: null, t: 0 };

function imagePoint(P) { return new THREE.Vector3(F * P.x / P.z, F * P.y / P.z, F); }
function imageFlow(P, V) {
  const z2 = P.z * P.z;
  return new THREE.Vector3(
    F * (V.x * P.z - P.x * V.z) / z2,
    F * (V.y * P.z - P.y * V.z) / z2,
    0
  );
}

const lblO = addLabel('<b>O</b>', new THREE.Vector3(), { fontSize: '26px', offset: [-20, 24] });
const lblP = addLabel('<b>P</b>', new THREE.Vector3(), { fontSize: '26px', offset: [26, 20] });
const lblp = addLabel('<b>p</b>', new THREE.Vector3(), { fontSize: '24px', offset: [2, 28] });
const lblPd = addLabel('<b>&#7766;</b>', new THREE.Vector3(), { fontSize: '26px', offset: [22, -22] });
const lblpd = addLabel('<b>&#7767;</b>', new THREE.Vector3(), { fontSize: '24px', offset: [-4, -24] });
[lblO, lblP, lblp, lblPd, lblpd].forEach(l => {
  l.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  l.div.style.fontWeight = '700';
});

const readout = document.getElementById('readout');

function updateFigure() {
  const P = state.P;
  const V = new THREE.Vector3(state.xdot, state.ydot, state.zdot);
