// @FIGURE_CODE_BEGIN
/* ── Element spec ───────────────────────────────────────────────────────────
   image plane quad → 4 × CylinderGeometry rods (r .042)      #1A1A1A
   camera centre O  → SphereGeometry(0.28)                    #1A1A1A
   3D point P       → SphereGeometry(0.30)                    #1A1A1A
   image point p    → SphereGeometry(0.155)                   #1A1A1A
   solid ray O→P    → CylinderGeometry rod (r .038)           #00E000
   dashed ray O→P+Ṗ → pool of rods, 0.22/0.14 dash (r .034)   #00E000
   arrow Ṗ at P     → cylinder shaft (r .07) + cone head      #FF0000
   arrow ṗ at p     → cylinder shaft (r .05) + cone head      #FF0000
   exact-tip bead   → SphereGeometry(0.085) at p+ṗ            #00A000
