}
quadRods.forEach(r => registerInteractive(r, {
  title: 'Image plane',
  tooltip: 'Image plane at Z = f',
  body: 'The image plane sits at Z = f = 2.5 in front of the camera centre O. Every 3D point is imaged where the ray from O to that point pierces this plane: x = fX/Z, y = fY/Z.'
}));

/* ── points, rays, arrows ─────────────────────────────────────────────────── */
const dotO = makeDot(0.28, DARK);
const dotP = makeDot(0.30, DARK);
const dotp = makeDot(0.155, DARK);
const rayRod = makeRod(GREEN);
const arrowP = makeArrow(RED, 0.07);
const arrowp = makeArrow(RED, 0.05);
const tipBead = makeDot(0.085, GREEN_D);

const dashPool = [];
for (let i = 0; i < 150; i++) {
  const r = makeRod(GREEN);
  r.visible = false;
  r.position.set(0, -50, 0);          // park off-frame so bounds stay clean
  r.scale.set(0.001, 0.001, 0.001);
  dashPool.push(r);
}
function setDashed(a, b, dash, gap, radius) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  let i = 0;
  if (len > 1e-6) {
