      const t2 = Math.min(t + dash, len);
      pa.copy(a).addScaledVector(dir, t);
      pb.copy(a).addScaledVector(dir, t2);
      setRod(dashPool[i], pa, pb, radius);
      i++; t = t2 + gap;
    }
  }
  for (; i < dashPool.length; i++) {
    dashPool[i].visible = false;
    dashPool[i].position.set(0, -50, 0);
    dashPool[i].scale.set(0.001, 0.001, 0.001);
  }
}

/* ── animation ghosts + trail ─────────────────────────────────────────────── */
const ghostP = makeDot(0.22, 0x444444, 0.55); ghostP.visible = false;
const ghostp = makeDot(0.12, 0x444444, 0.65); ghostp.visible = false;
const ghostRay = makeRod(GREEN, 0.45); ghostRay.visible = false;
