trailGeom.setAttribute('position', new THREE.BufferAttribute(trailPos, 3));
trailGeom.setDrawRange(0, 0);
const trailLine = new THREE.Line(trailGeom, new THREE.LineBasicMaterial({
  color: GREEN, transparent: true, opacity: 0.75
}));
trailLine.frustumCulled = false;
scene.add(trailLine);
let trailCount = 0;

/* ── state ────────────────────────────────────────────────────────────────── */
const state = {
  P: new THREE.Vector3(0.35, 1.0, 9.0),
  xdot: 0.2, ydot: 0.8, zdot: -2.0
};
const tween = { active: false, from: null, to: null, t: 0 };
let exagOn = true;
let currentK = 1;

function imagePoint(P) { return new THREE.Vector3(F * P.x / P.z, F * P.y / P.z, F); }
function imageFlow(P, V) {
  const z2 = P.z * P.z;
  return new THREE.Vector3(
    F * (V.x * P.z - P.x * V.z) / z2,
    F * (V.y * P.z - P.y * V.z) / z2,
    0
  );
}
/* Visual exaggeration: the ṗ arrow is kept at a readable on-screen length
   (~1.15 world units) while the numeric readout stays the exact derivative. */
function flowGain(len) {
  if (!exagOn || len < 1e-5) return 1;
  return THREE.MathUtils.clamp(1.15 / len, 1, 15);
}

