   +Y → screen-up, +X → recedes up-left.  f = 2.5.
─────────────────────────────────────────────────────────────────────────────*/

const F = 2.5;
const GREEN = 0x00E000, GREEN_D = 0x00A000, RED = 0xFF0000, DARK = 0x1A1A1A;
const UPV = new THREE.Vector3(0, 1, 0);

const CYL = new THREE.CylinderGeometry(1, 1, 1, 16);
const CONE = new THREE.ConeGeometry(1, 1, 22);
const SPH = new THREE.SphereGeometry(1, 28, 20);

function makeRod(color, opacity) {
  const m = new THREE.Mesh(CYL, new THREE.MeshBasicMaterial({
    color, transparent: opacity !== undefined, opacity: opacity === undefined ? 1 : opacity
  }));
  scene.add(m);
  return m;
}
function setRod(mesh, a, b, radius) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UPV, dir.clone().normalize());
  mesh.scale.set(radius, len, radius);
}
function makeDot(radius, color, opacity) {
  const m = new THREE.Mesh(SPH, new THREE.MeshBasicMaterial({
    color, transparent: opacity !== undefined, opacity: opacity === undefined ? 1 : opacity
  }));
  m.scale.setScalar(radius);
  scene.add(m);
  return m;
}
function makeArrow(color, shaftR) {
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(CYL, mat);
  const head = new THREE.Mesh(CONE, mat);
  const g = new THREE.Group();
  g.add(shaft); g.add(head);
  scene.add(g);
  return {
    group: g, shaft, head,
    set(origin, vec) {
      const len = vec.length();
      if (len < 1e-3) { g.visible = false; return; }
      g.visible = true;
      const dir = vec.clone().divideScalar(len);
      const q = new THREE.Quaternion().setFromUnitVectors(UPV, dir);
      const headLen = Math.min(len * 0.42, shaftR * 7.0);
      const headR = shaftR * 3.0;
      const shaftLen = Math.max(len - headLen, 1e-4);
      shaft.position.copy(origin).addScaledVector(dir, shaftLen / 2);
      shaft.quaternion.copy(q);
      shaft.scale.set(shaftR, shaftLen, shaftR);
      head.position.copy(origin).addScaledVector(dir, shaftLen + headLen / 2);
      head.quaternion.copy(q);
      head.scale.set(headR, headLen, headR);
    }
  };
}

/* ── image plane quad (Z = F, X ∈ [-1.7,1.7], Y ∈ [-2.6,2.6]) ─────────────── */
const HW = 1.7, HH = 2.6;
const quadCorners = [
  new THREE.Vector3(-HW, -HH, F), new THREE.Vector3(-HW, HH, F),
  new THREE.Vector3(HW, HH, F), new THREE.Vector3(HW, -HH, F)
];
const quadRods = [];
for (let i = 0; i < 4; i++) {
  const r = makeRod(DARK);
  setRod(r, quadCorners[i], quadCorners[(i + 1) % 4], 0.042);
  quadRods.push(r);
}
quadRods.forEach(r => registerInteractive(r, {
  title: 'Image plane',
  tooltip: 'Image plane at Z = f',
  body: 'The image plane sits at Z = f = 2.5 in front of the camera centre O. Every 3D point is imaged where the ray from O to that point pierces this plane: x = fX/Z, y = fY/Z.'
}));

/* ── points, rays, arrows ─────────────────────────────────────────────────── */
const dotO = makeDot(0.28, DARK);
const dotP = makeDot(0.30, DARK);
const dotp = makeDot(0.155, DARK);
const rayRod = makeRod(GREEN);
const arrowP = makeArrow(RED, 0.07);
const arrowp = makeArrow(RED, 0.05);
const tipBead = makeDot(0.085, GREEN_D);

const dashPool = [];
for (let i = 0; i < 150; i++) {
  const r = makeRod(GREEN);
  r.visible = false;
  r.position.set(0, -50, 0);          // park off-frame so bounds stay clean
  r.scale.set(0.001, 0.001, 0.001);
  dashPool.push(r);
}
function setDashed(a, b, dash, gap, radius) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  let i = 0;
  if (len > 1e-6) {
    dir.divideScalar(len);
    let t = 0;
    const pa = new THREE.Vector3(), pb = new THREE.Vector3();
    while (t < len && i < dashPool.length) {
      const t2 = Math.min(t + dash, len);
      pa.copy(a).addScaledVector(dir, t);
      pb.copy(a).addScaledVector(dir, t2);
      setRod(dashPool[i], pa, pb, radius);
      i++; t = t2 + gap;
    }
  }
  for (; i < dashPool.length; i++) {
    dashPool[i].visible = false;
    dashPool[i].position.set(0, -50, 0);
    dashPool[i].scale.set(0.001, 0.001, 0.001);
  }
}

/* ── animation ghosts + trail ─────────────────────────────────────────────── */
const ghostP = makeDot(0.22, 0x444444, 0.55); ghostP.visible = false;
const ghostp = makeDot(0.12, 0x444444, 0.65); ghostp.visible = false;
const ghostRay = makeRod(GREEN, 0.45); ghostRay.visible = false;
const TRAIL_MAX = 400;
const trailPos = new Float32Array(TRAIL_MAX * 3);
const trailGeom = new THREE.BufferGeometry();
trailGeom.setAttribute('position', new THREE.BufferAttribute(trailPos, 3));
trailGeom.setDrawRange(0, 0);
const trailLine = new THREE.Line(trailGeom, new THREE.LineBasicMaterial({
  color: GREEN, transparent: true, opacity: 0.75
}));
trailLine.frustumCulled = false;
scene.add(trailLine);
let trailCount = 0;

/* ── state ────────────────────────────────────────────────────────────────── */
const state = {
  P: new THREE.Vector3(0.35, 1.0, 9.0),
  xdot: 0.2, ydot: 0.8, zdot: -2.0
};
const tween = { active: false, from: null, to: null, t: 0 };
let exagOn = true;
let currentK = 1;

function imagePoint(P) { return new THREE.Vector3(F * P.x / P.z, F * P.y / P.z, F); }
function imageFlow(P, V) {
  const z2 = P.z * P.z;
  return new THREE.Vector3(
    F * (V.x * P.z - P.x * V.z) / z2,
    F * (V.y * P.z - P.y * V.z) / z2,
    0
  );
}
/* Visual exaggeration: the ṗ arrow is kept at a readable on-screen length
   (~1.15 world units) while the numeric readout stays the exact derivative. */
function flowGain(len) {
  if (!exagOn || len < 1e-5) return 1;
  return THREE.MathUtils.clamp(1.15 / len, 1, 15);
}

/* ── labels (heavy bold serif, sized like the source's typography) ────────── */
const lblO = addLabel('<b>O</b>', new THREE.Vector3(), { fontSize: '48px', offset: [-30, 40] });
const lblP = addLabel('<b>P</b>', new THREE.Vector3(), { fontSize: '48px', offset: [42, 34] });
const lblp = addLabel('<b>p</b>', new THREE.Vector3(), { fontSize: '42px', offset: [6, 40] });
const lblPd = addLabel('<b>&#7766;</b>', new THREE.Vector3(), { fontSize: '46px', offset: [28, -34] });
const lblpd = addLabel('<b>&#7767;</b>', new THREE.Vector3(), { fontSize: '42px', offset: [-8, -34] });
[lblO, lblP, lblp, lblPd, lblpd].forEach(l => {
  l.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  l.div.style.fontWeight = '700';
  l.div.style.color = '#000';
  l.div.style.lineHeight = '1';
});

const readout = document.getElementById('readout');
const kVal = document.getElementById('kVal');

function updateFigure() {
  const P = state.P;
  const V = new THREE.Vector3(state.xdot, state.ydot, state.zdot);
  const p = imagePoint(P);
  const pd = imageFlow(P, V);
  const O = new THREE.Vector3(0, 0, 0);
  const pdLen = pd.length();
  const K = flowGain(pdLen);
  currentK = K;

  dotO.position.copy(O);
  dotP.position.copy(P);
  dotp.position.copy(p);

  setRod(rayRod, O, P, 0.038);
  setDashed(O, P.clone().add(V), 0.22, 0.14, 0.034);

  arrowP.set(P, V);
  arrowp.set(p, pd.clone().multiplyScalar(K));

  const exactTip = p.clone().add(pd);
  tipBead.position.copy(exactTip);
  tipBead.visible = (K > 1.05 && pdLen > 1e-3);

  lblO.pos.copy(O);
  lblP.pos.copy(P);
  lblp.pos.copy(p);
  lblPd.pos.copy(P).addScaledVector(V, 0.55);
  lblpd.pos.copy(p).addScaledVector(pd, K);

  lblpd.div.innerHTML = (K > 1.05)
    ? '<b>&#7767;</b><span style="font-size:0.42em;font-weight:400;color:#c00;">&nbsp;×' + K.toFixed(1) + '</span>'
    : '<b>&#7767;</b>';

  kVal.textContent = '×' + K.toFixed(1);

  readout.innerHTML =
    `f = ${F}<br>` +
    `P  = (${P.x.toFixed(2)}, ${P.y.toFixed(2)}, ${P.z.toFixed(2)})<br>` +
    `P&#775;  = (${V.x.toFixed(2)}, ${V.y.toFixed(2)}, ${V.z.toFixed(2)})<br>` +
    `p  = (${p.x.toFixed(3)}, ${p.y.toFixed(3)})<br>` +
    `p&#775;  = (${pd.x.toFixed(3)}, ${pd.y.toFixed(3)})   |p&#775;| = ${pdLen.toFixed(3)}<br>` +
    `arrow drawn ×${K.toFixed(1)}`;
}

updateFigure();

/* ── camera (perspective, pose matched to the source) ─────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 215,      // +Z to screen-right, +X receding up-left (as in the figure)
  elevationDeg: 17,
  rollDeg: 0,
  heightFraction: 0.78,
  target: [0.1, 0.30, 4.0]
});

registerInteractive(dotP, {
  title: '3D point P',
  tooltip: 'Drag me — this is the moving 3D point P',
  body: 'P is the scene point with camera coordinates (X, Y, Z). Drag it: its image p always stays at the pierce point of the ray O→P, and the projected flow ṗ shrinks like 1/Z as P moves away.'
});
registerInteractive(dotp, {
  title: 'Image point p',
  tooltip: 'p = (fX/Z, fY/Z)',
  body: 'p is the perspective projection of P onto the image plane: x = fX/Z, y = fY/Z. Its velocity ṗ = (ẋ, ẏ) is the time derivative of those expressions — the optical flow.'
});
registerInteractive(arrowP.group, {
  title: '3D velocity Ṗ',
  tooltip: 'Ṗ = (Ẋ, Ẏ, Ż)',
  body: 'The instantaneous 3D velocity of P, drawn with Δt = 1 so its tip is at P + Ṗ — exactly the point the dashed ray passes through. It generally has a depth component Ż, which is why the image flow is not just a rescaled copy of this arrow.'
});
registerInteractive(arrowp.group, {
  title: '2D optical flow ṗ',
  tooltip: 'ẋ = f(ẊZ − XŻ)/Z²',
  body: 'ṗ lies entirely in the image plane: ẋ = f(ẊZ − XŻ)/Z², ẏ = f(ẎZ − YŻ)/Z². For readability the arrow is drawn exaggerated (the factor is shown next to the label); the green bead marks its true length, and the readout is always the exact value.'
});
registerInteractive(tipBead, {
  title: 'True tip of ṗ',
  tooltip: 'Exact p + ṗ (Δt = 1)',
  body: 'This bead is the un-exaggerated endpoint p + ṗ. Turn the exaggeration off in the panel to see the arrow shrink onto it — and notice how far p + ṗ falls from the plain rescaling of Ṗ.'
});

/* ── controls: sliders ────────────────────────────────────────────────────── */
const sx = document.getElementById('xdot');
const sy = document.getElementById('ydot');
const sz = document.getElementById('zdot');
const vxVal = document.getElementById('vxVal');
const vyVal = document.getElementById('vyVal');
const vzVal = document.getElementById('vzVal');

function syncSliderLabels() {
  vxVal.textContent = state.xdot.toFixed(2);
  vyVal.textContent = state.ydot.toFixed(2);
  vzVal.textContent = state.zdot.toFixed(2);
}
function readSliders() {
  state.xdot = parseFloat(sx.value);
  state.ydot = parseFloat(sy.value);
  state.zdot = parseFloat(sz.value);
  syncSliderLabels();
  updateFigure();
}
[sx, sy, sz].forEach(s => s.addEventListener('input', () => {
  tween.active = false;
  readSliders();
}));
syncSliderLabels();

document.getElementById('exag').addEventListener('change', (e) => {
  exagOn = e.target.checked;
  updateFigure();
});

/* ── control: drag P ──────────────────────────────────────────────────────── */
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const dragHit = new THREE.Vector3();
let dragging = false;

function pointerNDC(ev) {
  const r = canvas.getBoundingClientRect();
  dragPtr.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  dragPtr.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (ev) => {
  pointerNDC(ev);
  dragRay.setFromCamera(dragPtr, camera);
  const hits = dragRay.intersectObject(dotP, false);
  if (hits.length) {
    dragging = true;
    controls.enabled = false;
    const n = new THREE.Vector3();
    camera.getWorldDirection(n);
    dragPlane.setFromNormalAndCoplanarPoint(n, state.P.clone());
    canvas.style.cursor = 'grabbing';
  }
}, true);
window.addEventListener('pointermove', (ev) => {
  if (!dragging) return;
  pointerNDC(ev);
  dragRay.setFromCamera(dragPtr, camera);
  if (!dragRay.ray.intersectPlane(dragPlane, dragHit)) return;
  const Z = THREE.MathUtils.clamp(dragHit.z, 3, 16);
  const maxX = 1.5 * Z / F, maxY = 2.35 * Z / F;
  const X = THREE.MathUtils.clamp(dragHit.x, -maxX, maxX);
  const Y = THREE.MathUtils.clamp(dragHit.y, -maxY, maxY);
  state.P.set(X, Y, Z);
  updateFigure();
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'grab'; }
});

/* ── control: animation ───────────────────────────────────────────────────── */
const btnPlay = document.getElementById('playMotion');
let playing = false, phase = 0;
btnPlay.addEventListener('click', () => {
  playing = !playing;
  btnPlay.classList.toggle('active', playing);
  btnPlay.textContent = playing ? '❚❚ Pause motion' : '▶ Advance P along Ṗ';
  if (!playing) {
    ghostP.visible = ghostp.visible = ghostRay.visible = false;
    trailCount = 0; trailGeom.setDrawRange(0, 0);
  } else { phase = 0; trailCount = 0; }
});

/* ── demo steps ───────────────────────────────────────────────────────────── */
const STEPS = [
  { title: '1. The projection ray',
    text: 'With almost no motion, only the geometry remains: the green ray from camera centre O through P pierces the image plane at p, the projection of P.',
    state: { xdot: 0, ydot: 0, zdot: 0 } },
  { title: '2. Pure lateral motion',
    text: 'Give P a purely sideways velocity Ẋ. The red arrow at p is parallel to it and scaled by f/Z — the same world speed appears slower when the point is far away.',
    state: { xdot: 2, ydot: 0, zdot: 0 } },
  { title: '3. Pure motion in depth',
    text: 'Now move P only along the optical axis. The 3D arrow points straight away from the camera, yet the image flow ṗ points radially outward from the image centre — proof that ṗ is a projection, not a rescaling, of Ṗ.',
    state: { xdot: 0, ydot: 0, zdot: 2.5 } },
  { title: '4. General 3D velocity',
    text: 'Combine all three components to reproduce the textbook figure: the dashed ray through the displaced point P+Ṗ pierces the plane at p+ṗ (the green bead).',
    state: { xdot: 0.2, ydot: 0.8, zdot: -2 } }
];
let stepIdx = 3;
const stepTitle = document.getElementById('stepTitle');
const narration = document.getElementById('narration');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.title;
  narration.textContent = s.text;
  tween.from = { xdot: state.xdot, ydot: state.ydot, zdot: state.zdot };
  tween.to = { xdot: s.state.xdot, ydot: s.state.ydot, zdot: s.state.zdot };
  tween.t = 0;
  tween.active = true;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(3);

/* ── local update loop (scaffold owns rendering) ──────────────────────────── */
let lastT = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;

  if (tween.active) {
    tween.t = Math.min(1, tween.t + dt / 0.8);
    const e = tween.t < 0.5 ? 2 * tween.t * tween.t : -1 + (4 - 2 * tween.t) * tween.t;
    state.xdot = tween.from.xdot + (tween.to.xdot - tween.from.xdot) * e;
    state.ydot = tween.from.ydot + (tween.to.ydot - tween.from.ydot) * e;
    state.zdot = tween.from.zdot + (tween.to.zdot - tween.from.zdot) * e;
    sx.value = state.xdot; sy.value = state.ydot; sz.value = state.zdot;
    syncSliderLabels();
    updateFigure();
    if (tween.t >= 1) tween.active = false;
  }

  if (playing) {
    phase += dt / 2.6;
    if (phase > 1) { phase = 0; trailCount = 0; }
    const V = new THREE.Vector3(state.xdot, state.ydot, state.zdot);
    const Pg = state.P.clone().addScaledVector(V, phase);
    if (Pg.z > 0.3) {
      const pg = imagePoint(Pg);
      ghostP.visible = ghostp.visible = ghostRay.visible = true;
      ghostP.position.copy(Pg);
      ghostp.position.copy(pg);
      setRod(ghostRay, new THREE.Vector3(0, 0, 0), Pg, 0.016);
      if (trailCount < TRAIL_MAX) {
        trailPos[trailCount * 3] = pg.x;
        trailPos[trailCount * 3 + 1] = pg.y;
        trailPos[trailCount * 3 + 2] = pg.z;
        trailCount++;
        trailGeom.setDrawRange(0, trailCount);
        trailGeom.attributes.position.needsUpdate = true;
      }
    }
  }
}
requestAnimationFrame(tick);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

